import sys

def main():
    lines = sys.stdin.read().splitlines()
    my_name = lines[0]
    n = int(lines[1])

    priorities = {}

    for i in range(2, 2 + n):
        parts = lines[i].split()
        x = parts[0]

        if parts[1] == "posted":
            y = parts[3].rstrip("'")
            score = 15
        elif parts[1] == "commented":
            y = parts[3].rstrip("'")
            score= 10
        elif parts[1] == "likes":
            y = parts[3].rstrip("'")
            score 5

        if x != my_name and y != my_name:
            continue

        if x == my_name:
            if y not in priorities:
                priorities[y] = 0
            priorities[y] += score
        elif y == my_name:
            if x not in priorities:
                priorities[x] = 0
            priorities[x] += score

    names = list(priorities.keys())
    names.sort(key=lambda name: (-priorities[name], name))

